    tau = ops.softplus(_scalar(tau0)) + _scalar(tau1) * g2
    w = ops.clamp(1.0 + _scalar(k) * g2, w_min, w_max) * base_weight

    loss_vec = w * ops.softplus((-alpha_t * d) / (tau + eps_t))
    return loss_vec.mean()

def generated_loss(batch, model_output, extra):
    src = extra if isinstance(extra, dict) else {}

    def _get(key, default=None):
        if isinstance(src, dict) and key in src:
            return src[key]
        if isinstance(batch, dict) and key in batch:
            return batch[key]
        return default

    log_prob_w = _get("log_prob_w")
    log_prob_l = _get("log_prob_l")
    delta_z = _get("delta_z")
    base_weight = _get("weight", None)

    hp = src.get("hyperparams", {}) if isinstance(src, dict) else {}
    alpha = float(_get("alpha", hp.get("alpha", 1.0)))
    beta = float(_get("beta", hp.get("beta", 1.0)))
    g2_max = float(_get("g2_max", hp.get("g2_max", 25.0)))
    s_min = float(_get("s_min", hp.get("s_min", 0.25)))
    s_max = float(_get("s_max", hp.get("s_max", 4.0)))
    eps = float(_get("eps", hp.get("eps", 1e-8)))

    # Stable differentiable zero if missing required tensors.
    if log_prob_w is None or log_prob_l is None:
        if log_prob_w is not None:
            return (log_prob_w * 0.0).mean()
        if log_prob_l is not None:
            return (log_prob_l * 0.0).mean()
        return ops.tensor(0.0)

    d = log_prob_w - log_prob_l

    # Default weight to 1.0 with correct dtype/device via d.
    if base_weight is None:
        base_weight = d * 0.0 + 1.0

    # Helper to create a scalar tensor on the same device/dtype as d.
    def _scalar(x):
        return d * 0.0 + float(x)

    alpha_t = _scalar(alpha)
    base_loss = ops.softplus(-alpha_t * d)

    # If no gap info, fall back to standard weighted BT softplus.
    if delta_z is None:
        return (base_weight * base_loss).mean()

    # Smooth, bounded sensitivity to objective/gap: larger |gap| => larger weight.
    g = ops.zscore(delta_z, eps=eps)
    g2 = ops.clamp(g * g, 0.0, g2_max)

    # softplus ensures positivity; clamp avoids extreme scaling.
    s = ops.clamp(ops.softplus(_scalar(beta) * g2), s_min, s_max)
    w = base_weight * s

    return (w * base_loss).mean()

def generated_loss(batch, model_output, extra):
    # Be tolerant to different harnesses: values may live in batch, model_output, or extra.
    srcs = []
    if isinstance(extra, dict):
        srcs.append(extra)
        hp = extra.get("hyperparams", {}) if isinstance(extra.get("hyperparams", {}), dict) else {}
    else:
        hp = {}
    if isinstance(batch, dict):
        srcs.append(batch)
    if isinstance(model_output, dict):
        srcs.append(model_output)

    def get_first(key, default=None):
        for s in srcs:
            if key in s:
                return s[key]
        return default

    log_prob_w = get_first("log_prob_w", None)
    log_prob_l = get_first("log_prob_l", None)
    delta_z = get_first("delta_z", None)
    base_weight = get_first("weight", None)

    # If required keys are missing, return a safe zero that keeps autograd happy.
    if log_prob_w is None or log_prob_l is None or delta_z is None:
        ref = log_prob_w if log_prob_w is not None else (log_prob_l if log_prob_l is not None else delta_z)
        if ref is not None:
            return (ref * 0.0).mean()
        return (get_first("loss_ref", 0.0) * 0.0)

    alpha = float(get_first("alpha", hp.get("alpha", 1.0)))
    tau0 = float(get_first("tau0", hp.get("tau0", 0.5)))
    tau1 = float(get_first("tau1", hp.get("tau1", 0.5)))
    g_max = float(get_first("g_max", hp.get("g_max", 3.0)))
    k = float(get_first("k", hp.get("k", 0.5)))
    w_min = float(get_first("w_min", hp.get("w_min", 0.25)))
    w_max = float(get_first("w_max", hp.get("w_max", 4.0)))
    eps = float(get_first("eps", hp.get("eps", 1e-8)))

    d = log_prob_w - log_prob_l

    g_n = ops.zscore(delta_z, eps=eps)
    g_mag = ops.clamp(ops.abs(g_n), 0.0, g_max)

    tau = ops.softplus(tau0) + tau1 * g_mag

    w = ops.clamp(1.0 + k * g_mag, w_min, w_max)
    if base_weight is not None:
        w = w * base_weight

    loss_vec = w * ops.softplus(-alpha * d / (tau + eps))
    return loss_vec.mean()
